package com.mailsent.evidence.domain;

import java.time.Instant;
import java.util.Objects;
import java.util.UUID;

/**
 * EvidenceExport — EVID-003 Evidence API/export.
 *
 * <p>Represents a formalized, immutable snapshot of evidence lineage intended
 * for external consumption (e.g., an auditor or client). It encapsulates the trace
 * data generated by EVID-001 and EVID-002 into a portable boundary.</p>
 */
public class EvidenceExport {

    public enum ExportFormat {
        JSON,
        CSV,
        PDF
    }

    private final String id;
    private final String targetId; // domain or portfolio
    private final String requestingUserId;
    private final ExportFormat format;
    private final Instant requestedAt;

    private EvidenceExport(String id, String targetId, String requestingUserId, 
                           ExportFormat format, Instant requestedAt) {
        this.id = Objects.requireNonNull(id);
        this.targetId = Objects.requireNonNull(targetId);
        this.requestingUserId = Objects.requireNonNull(requestingUserId);
        this.format = Objects.requireNonNull(format);
        this.requestedAt = Objects.requireNonNull(requestedAt);
    }

    /**
     * Requests a new formalized evidence export.
     *
     * @param targetId         the identity of the domain or portfolio
     * @param requestingUserId the user requesting the export for audit tracking
     * @param format           the requested output format
     * @param requestedAt      the deterministic timestamp of the request
     * @return a new EvidenceExport request
     */
    public static EvidenceExport request(String targetId, String requestingUserId, 
                                         ExportFormat format, Instant requestedAt) {
        return new EvidenceExport(UUID.randomUUID().toString(), targetId, requestingUserId, format, requestedAt);
    }

    public String id() { return id; }
    public String targetId() { return targetId; }
    public String requestingUserId() { return requestingUserId; }
    public ExportFormat format() { return format; }
    public Instant requestedAt() { return requestedAt; }
}
